param location string = resourceGroup().location
param sqlServerName string = 'northbank-sql-primary'
param logAnalyticsWorkspaceId string

resource sqlServer 'Microsoft.Sql/servers@2023-05-01-preview' = {
  name: sqlServerName
  location: location
  identity: { type: 'SystemAssigned' }
  properties: {
    minimalTlsVersion: '1.2'
    publicNetworkAccess: 'Disabled'
  }
}

resource paymentsDb 'Microsoft.Sql/servers/databases@2023-05-01-preview' = {
  parent: sqlServer
  name: 'payments'
  location: location
  sku: {
    name: 'BC_Gen5'          // Business Critical: 3 extra replicas
    tier: 'BusinessCritical'
    family: 'Gen5'
    capacity: 4
  }
  properties: {
    zoneRedundant: true       // replicas spread across availability zones
    requestedBackupStorageRedundancy: 'GeoZone'
    readScale: 'Enabled'
  }
}

resource tde 'Microsoft.Sql/servers/databases/transparentDataEncryption@2023-05-01-preview' = {
  parent: paymentsDb
  name: 'current'
  properties: { state: 'Enabled' }
}

resource shortTermBackup 'Microsoft.Sql/servers/databases/backupShortTermRetentionPolicies@2023-05-01-preview' = {
  parent: paymentsDb
  name: 'default'
  properties: { retentionDays: 35, diffBackupIntervalInHours: 12 }
}

resource longTermBackup 'Microsoft.Sql/servers/databases/backupLongTermRetentionPolicies@2023-05-01-preview' = {
  parent: paymentsDb
  name: 'default'
  properties: { weeklyRetention: 'P12W', monthlyRetention: 'P12M', yearlyRetention: 'P7Y', weekOfYear: 1 }
}

resource auditing 'Microsoft.Sql/servers/auditingSettings@2023-05-01-preview' = {
  parent: sqlServer
  name: 'default'
  properties: {
    state: 'Enabled'
    isAzureMonitorTargetEnabled: true
    auditActionsAndGroups: [
      'BATCH_COMPLETED_GROUP'
      'SUCCESSFUL_DATABASE_AUTHENTICATION_GROUP'
      'FAILED_DATABASE_AUTHENTICATION_GROUP'
    ]
  }
}

resource auditDiag 'Microsoft.Insights/diagnosticSettings@2021-05-01-preview' = {
  scope: paymentsDb
  name: 'sql-audit-to-law'
  properties: {
    workspaceId: logAnalyticsWorkspaceId
    logs: [ { category: 'SQLSecurityAuditEvents', enabled: true } ]
  }
}

param primaryServerId string
param secondaryServerId string
param paymentsDbId string

resource failoverGroup 'Microsoft.Sql/servers/failoverGroups@2023-05-01-preview' = {
  name: '${last(split(primaryServerId, '/'))}/northbank-payments-fog'
  properties: {
    readWriteEndpoint: {
      failoverPolicy: 'Automatic'
      failoverWithDataLossGracePeriodMinutes: 60
    }
    partnerServers: [ { id: secondaryServerId } ]
    databases: [ paymentsDbId ]
  }
}
// Connection strings must use: northbank-payments-fog.database.windows.net

builder.Services.AddDbContextPool<PaymentsDbContext>(options =>
    options.UseSqlServer(
        builder.Configuration.GetConnectionString("PaymentsDb"),
        sql =>
        {
            sql.EnableRetryOnFailure(
                maxRetryCount: 3,
                maxRetryDelay: TimeSpan.FromSeconds(5),
                errorNumbersToAdd: null);
            sql.CommandTimeout(3); // seconds - matches f4 timeoutMs = 3000
        }));

// appsettings.json connection string (no secrets in code):
// "PaymentsDb": "Server=tcp:northbank-payments-fog.database.windows.net,1433;Database=payments;Authentication=Active Directory Default;Encrypt=True;TrustServerCertificate=False;Connect Timeout=5"

builder.Services.AddDbContext<SettlementDbContext>(options =>
    options.UseSqlServer(
        builder.Configuration.GetConnectionString("PaymentsDb"),
        sql =>
        {
            sql.EnableRetryOnFailure(
                maxRetryCount: 3,
                maxRetryDelay: TimeSpan.FromSeconds(10));
            sql.CommandTimeout(5); // seconds - matches f8 timeoutMs = 5000
        }));
